var e={concepto:"El trapecio aproxima la curva con rectas y por eso necesita muchos trozos para ser preciso. Simpson da un paso m\xE1s: toma tres puntos consecutivos y hace pasar por ellos una par\xE1bola. El \xE1rea bajo esa par\xE1bola se calcula exactamente y resulta una f\xF3rmula muy simple. Encadenando par\xE1bolas de dos en dos subintervalos se obtiene una aproximaci\xF3n mucho mejor con el mismo trabajo de tabla.",fundamento:"Por tres puntos pasa una \xFAnica par\xE1bola. Integr\xE1ndola entre los extremos sale (h/3)\xB7[f(x\u2080) + 4f(x\u2081) + f(x\u2082)] para un bloque de dos subintervalos. Al unir varios bloques, los nodos impares quedan con coeficiente 4, los pares interiores con 2 y los extremos con 1. Como la par\xE1bola reproduce exactamente polinomios de grado \u2264 3, Simpson acierta la integral de cualquier c\xFAbica con cualquier n par, sin necesidad de refinar, algo que el trapecio no logra. Esa es la raz\xF3n profunda de su orden 4.",cuandoFalla:"Primero, exige n par: cada par\xE1bola cubre dos subintervalos, y con n impar el \xFAltimo queda suelto. Segundo, necesita que f sea suave en [a, b]; una discontinuidad o un pico dentro del intervalo hace que la par\xE1bola atraviese el salto y el resultado no converja. Tercero, no sirve para datos tabulados con espaciado irregular: los nodos tienen que estar igualmente separados. Y cuarto, con muy pocos puntos puede dar una falsa sensaci\xF3n de precisi\xF3n: un n = 2 puede ajustar una par\xE1bola que no tiene nada que ver con la funci\xF3n real.",precision:"El error de Simpson es \u2212(b \u2212 a)\xB7h\u2074\xB7f\u2057(\u03BE)/180: de orden h\u2074. Al duplicar n, el error baja a la dieciseisava parte, mucho m\xE1s r\xE1pido que el trapecio (h\xB2). En la pr\xE1ctica, con la mitad de puntos se obtiene m\xE1s precisi\xF3n que con el trapecio. La contracara es que el error depende de la cuarta derivada: si f\u2057 es enorme (funciones muy oscilantes), la ventaja se reduce, y si f no es suave, la f\xF3rmula del error deja de valer.",videoUrl:"https://www.youtube.com/results?search_query=regla+de+simpson+1/3+compuesta+ejemplo",recursos:[{titulo:"Regla de Simpson (Wikipedia, espa\xF1ol)",url:"https://es.wikipedia.org/wiki/Regla_de_Simpson",tipo:"lectura",descripcion:"La deducci\xF3n por par\xE1bolas, la versi\xF3n compuesta y el t\xE9rmino de error."},{titulo:"Integraci\xF3n num\xE9rica (Wikipedia, espa\xF1ol)",url:"https://es.wikipedia.org/wiki/Integraci%C3%B3n_num%C3%A9rica",tipo:"lectura",descripcion:"Comparaci\xF3n entre trapecio, Simpson y cuadratura gaussiana."},{titulo:"Simpson\u2019s Rule (MathWorld)",url:"https://mathworld.wolfram.com/SimpsonsRule.html",tipo:"lectura",descripcion:"La f\xF3rmula, los coeficientes y la relaci\xF3n con la regla de los tres octavos."},{titulo:"Calculus Grapher (PhET, simulaci\xF3n)",url:"https://phet.colorado.edu/es/simulations/calculus-grapher",tipo:"interactivo",descripcion:"Compar\xE1 visualmente el \xE1rea real con las aproximaciones por trozos."},{titulo:"Videos de repaso: Simpson 1/3",url:"https://www.youtube.com/results?search_query=regla+de+simpson+1/3+compuesta+ejercicios+resueltos",tipo:"video",descripcion:"Ejemplos con la tabla 1-4-2-4-1 y comparaci\xF3n contra el valor exacto."}],algoritmo:{formula:"I \u2248 (h/3) \xB7 [ f(x\u2080) + 4f(x\u2081) + 2f(x\u2082) + 4f(x\u2083) + \u2026 + f(x\u2099) ]      h = (b \u2212 a)/n,  n par",formulaTex:"I \\approx \\frac{h}{3}\\left[f(x_0)+4f(x_1)+2f(x_2)+4f(x_3)+\\cdots+f(x_n)\\right], \\quad h=\\frac{b-a}{n},\\ n\\text{ par}",criterios:[{nombre:"n par obligatorio",explicacion:"Cada par\xE1bola cubre dos subintervalos. Con n impar, el \xFAltimo trozo queda sin pareja y la f\xF3rmula no aplica."},{nombre:"Coeficientes 1, 4, 2, 4, \u2026",explicacion:"Extremos 1, nodos impares 4, nodos pares interiores 2. Es la firma de Simpson y hay que verificarla en la tabla."},{nombre:"Error de orden h\u2074",explicacion:"Al duplicar n, el error baja a la dieciseisava parte. Es la comprobaci\xF3n pr\xE1ctica de que el resultado es confiable."},{nombre:"Valor exacto (opcional)",explicacion:"Si se conoce, el error real es |I aproximada \u2212 I exacta|. Si no, se compara con n duplicado."}],pasos:["Identificar f(x), el intervalo [a, b] y elegir un n PAR de subintervalos.","Calcular h = (b \u2212 a)/n y los nodos x\u1D62 = a + i\xB7h, para i = 0, 1, \u2026, n.","Evaluar f en cada nodo y asignar coeficientes: 1 en los extremos, 4 en los impares, 2 en los pares interiores.","Sumar los aportes coeficiente \xB7 f(x\u1D62).","Multiplicar por h/3: ese es el valor aproximado de la integral.","Si se conoce el valor exacto, medir el error; si no, repetir con n duplicado y comparar."],ventajas:["Con la misma cantidad de nodos que el trapecio, da mucha m\xE1s precisi\xF3n (orden h\u2074 contra h\xB2).","Es exacta para polinomios de grado \u2264 3.","La tabla es igual de simple que la del trapecio: solo cambian los coeficientes.","El error se estima sin derivadas, comparando dos valores de n."],limitaciones:["Exige n par; con n impar hay que cambiar de m\xE9todo o de n.","Requiere nodos igualmente espaciados (no sirve para tablas irregulares).","Si la funci\xF3n tiene una discontinuidad o un pico, la par\xE1bola lo atraviesa y el error no baja.","El orden 4 depende de que f tenga cuarta derivada razonable: con funciones muy oscilantes hay que refinar igual."],recomendaciones:["Verific\xE1 siempre que n sea par antes de calcular.","Compar\xE1 con el trapecio en el mismo n: la diferencia muestra el valor de usar par\xE1bolas.","Duplic\xE1 n y comprob\xE1 que el error baja cerca de 16 veces; si no, sospech\xE1 de una discontinuidad.","Para datos tabulados con espaciado irregular, no uses Simpson: interpol\xE1 o us\xE1 trapecio."]},ejemploNormal:{id:"si-num-1",titulo:"Integral de x\xB2 en [0, 1] con Simpson y cuatro subintervalos",tipo:"numerico",planteamiento:"Aproximar \u222B\u2080\xB9 x\xB2 dx con Simpson 1/3 compuesto usando n = 4, y comprobar que el resultado es exacto.",parametros:[{etiqueta:"f(x)",valor:"x\xB2"},{etiqueta:"Intervalo",valor:"[0, 1]"},{etiqueta:"n",valor:"4 (par)"},{etiqueta:"Valor exacto",valor:"1/3 = 0.333333"}],formula:"\u222B\u2080\xB9 x\xB2 dx \u2248 (0.25/3) \xB7 [0 + 4(0.0625) + 2(0.25) + 4(0.5625) + 1]",formulaTex:"\\int_0^1 x^2\\,dx \\approx \\frac{0.25}{3}\\left[0+4(0.0625)+2(0.25)+4(0.5625)+1\\right]",interpretacion:"x\xB2 es una par\xE1bola, as\xED que Simpson la reproduce exactamente: el resultado tiene que dar 1/3 sin error. Es la mejor forma de ver por qu\xE9 el m\xE9todo es exacto para polinomios de grado \u2264 3.",pasos:["h = (1 \u2212 0)/4 = 0.25. Nodos: 0; 0.25; 0.5; 0.75; 1.","f evaluada: 0; 0.0625; 0.25; 0.5625; 1.","Coeficientes 1-4-2-4-1: suma = 0 + 0.25 + 0.5 + 2.25 + 1 = 4.","Integral: I \u2248 (0.25/3)\xB74 = 1/3 = 0.333333. Error: 0."],algoritmo:"Se aplican los coeficientes 1-4-2-4-1 a los cinco nodos y se multiplica la suma por h/3.",criterio:"El error es exactamente cero porque la funci\xF3n es un polinomio de grado 2 y Simpson es exacta hasta grado 3. Si se cambiara por x\u2074, ya no ser\xEDa exacta y habr\xEDa que aumentar n.",conclusion:"La integral aproximada es 0.333333, id\xE9ntica al valor exacto 1/3. El m\xE9todo no tuvo error porque la par\xE1bola que ajusta cada bloque coincide con la funci\xF3n. Esto no pasa con cualquier funci\xF3n: es una propiedad de los polinomios de grado \u2264 3.",calculo:{funcion:"x^2",a:0,b:1,n:4,valorExacto:.3333333333333333,etiqueta:"x\xB2 en [0, 1]"}},ejemploCasuistica:{id:"si-cas-1",titulo:"\xC1rea bajo un arco de seno",tipo:"casuistica",enunciado:"La forma de un techo paraboloide se modela con y = sin(x) entre 0 y \u03C0. El \xE1rea del perfil es A = \u222B de 0 a \u03C0 sin(x) dx, que vale exactamente 2. Calcularla con Simpson y n = 6 para verificar el dise\xF1o.",extraccion:{busqueda:"Se busca el \xE1rea bajo el perfil del techo, integrando la altura y(x).",datos:[{simbolo:"y",valor:"sin(x)",queEs:"Altura del perfil en cada punto del ancho."},{simbolo:"x",valor:"de 0 a \u03C0",queEs:"Ancho del techo, en radianes."},{simbolo:"A",valor:"\u222B de 0 a \u03C0 sin(x) dx",queEs:"\xC1rea del perfil, en unidades cuadradas."}],formulacion:"El \xE1rea es la integral de la altura. Como el seno es suave, Simpson con pocos bloques ya da una aproximaci\xF3n excelente: es el caso t\xEDpico de aplicaci\xF3n en dise\xF1o."},planteamiento:"Aproximar A = \u222B de 0 a \u03C0 sin(x) dx con Simpson y n = 6, y comparar con 2.",parametros:[{etiqueta:"f(x)",valor:"sin(x)"},{etiqueta:"Intervalo",valor:"[0, \u03C0]"},{etiqueta:"n",valor:"6 (par)"},{etiqueta:"Valor exacto",valor:"2"}],formula:"A \u2248 (\u03C0/18) \xB7 [0 + 4(0.5) + 2(0.8660254) + 4(1) + 2(0.8660254) + 4(0.5) + 0]",formulaTex:"A \\approx \\frac{\\pi}{18}\\left[0+4(0.5)+2(0.8660254)+4(1)+2(0.8660254)+4(0.5)+0\\right]",interpretacion:"Con solo seis subintervalos, tres par\xE1bolas cubren todo el arco. El resultado va a quedar muy cerca de 2: el error de Simpson baja como h\u2074, y h = \u03C0/6 \u2248 0.52 no es tan chico.",pasos:["h = \u03C0/6 \u2248 0.5235988. Nodos: 0; \u03C0/6; \u03C0/3; \u03C0/2; 2\u03C0/3; 5\u03C0/6; \u03C0.","f evaluada: 0; 0.5; 0.8660254; 1; 0.8660254; 0.5; 0.","Coeficientes 1-4-2-4-2-4-1: suma = 0 + 2 + 1.7320508 + 4 + 1.7320508 + 2 + 0 = 11.4641016.","\xC1rea: A \u2248 (0.5235988/3)\xB711.4641016 = 2.0008632. Error: 0.0008632 (0.043 %)."],algoritmo:"Se eval\xFAa el seno en los siete nodos, se aplican los coeficientes 1-4-2-4-2-4-1 y se multiplica por h/3.",criterio:"El exacto es 2. Simpson da 2.0008632: un 0.043 % alto. Con n = 4, en cambio, el error es 0.228 %: al pasar de 4 a 6 nodos ya mejora unas cinco veces.",conclusion:"El \xE1rea calculada es 2.0008632, contra 2 exacta: un error de 0.0008632 (0.043 %). Para un c\xE1lculo de dise\xF1o es m\xE1s que suficiente, y con n = 12 el error bajar\xEDa a la dieciseisava parte (0.0027 %).",calculo:{funcion:"sin(x)",a:0,b:Math.PI,n:6,valorExacto:2,etiqueta:"\xC1rea bajo sin(x) en [0, \u03C0]"}}},o=[{id:"si-num-2",titulo:"Integral de 1/x en [1, 2] con Simpson",tipo:"numerico",planteamiento:"Aproximar \u222B\u2081\xB2 (1/x) dx con n = 4 y comparar con ln(2) = 0.6931472.",parametros:[{etiqueta:"f(x)",valor:"1/x"},{etiqueta:"Intervalo",valor:"[1, 2]"},{etiqueta:"n",valor:"4 (par)"},{etiqueta:"Valor exacto",valor:"ln 2 = 0.6931472"}],formula:"\u222B\u2081\xB2 (1/x) dx \u2248 (0.25/3) \xB7 [1 + 4(0.8) + 2(0.6666667) + 4(0.5714286) + 0.5]",formulaTex:"\\int_1^2 \\frac{1}{x}\\,dx \\approx \\frac{0.25}{3}\\left[1+4(0.8)+2(0.6666667)+4(0.5714286)+0.5\\right]",interpretacion:"Es el mismo ejemplo que en el trapecio, con el mismo n. Comparar los dos resultados deja ver la diferencia de orden: trapecio 0.6970238, Simpson 0.6932540, exacto 0.6931472.",pasos:["h = 0.25. Nodos: 1; 1.25; 1.5; 1.75; 2.","f evaluada: 1; 0.8; 0.6666667; 0.5714286; 0.5.","Suma con coeficientes 1-4-2-4-1: 1 + 3.2 + 1.3333333 + 2.2857143 + 0.5 = 8.3190476.","I \u2248 (0.25/3)\xB78.3190476 = 0.6932540. Error: 0.0001068 (0.015 %)."],algoritmo:"Coeficientes 1-4-2-4-1 sobre cuatro subintervalos.",criterio:"ln(2) = 0.6931472. Simpson da 0.6932540: 0.015 % alto, unas 36 veces mejor que el trapecio con el mismo n (0.56 %).",conclusion:"La integral aproximada es 0.6932540, con un error absoluto de 0.0001068. Frente al trapecio, que necesitaba duplicar varias veces n para acercarse, Simpson llega con cuatro trozos al mismo orden de precisi\xF3n.",calculo:{funcion:"1/x",a:1,b:2,n:4,valorExacto:Math.LN2,etiqueta:"1/x en [1, 2]"}},{id:"si-cas-2",titulo:"Volumen de un tanque de perfil c\xFAbico",tipo:"casuistica",enunciado:"Un tanque tiene secci\xF3n transversal A(h) = h\xB3 + 1 m\xB2 a la altura h, entre 0 y 2 m. El volumen total es V = \u222B\u2080\xB2 (h\xB3 + 1) dh, que vale exactamente 6 m\xB3. Verificar el c\xE1lculo con Simpson y n = 4.",extraccion:{busqueda:"Se busca el volumen acumulado integrando el \xE1rea de la secci\xF3n transversal.",datos:[{simbolo:"A(h)",valor:"h\xB3 + 1 m\xB2",queEs:"\xC1rea de la secci\xF3n a cada altura."},{simbolo:"h",valor:"de 0 a 2 m",queEs:"Altura del tanque."},{simbolo:"V",valor:"\u222B\u2080\xB2 A(h) dh",queEs:"Volumen total, en m\xB3."}],formulacion:"El volumen es la integral del \xE1rea por la altura. Como A es un polinomio de grado 3, Simpson debe dar el valor exacto: es la prueba de que reproduce c\xFAbicas."},planteamiento:"Aproximar V = \u222B\u2080\xB2 (h\xB3 + 1) dh con Simpson y n = 4, y comparar con 6 m\xB3.",parametros:[{etiqueta:"A(h)",valor:"h\xB3 + 1"},{etiqueta:"Intervalo",valor:"[0, 2] m"},{etiqueta:"n",valor:"4 (par)"},{etiqueta:"Valor exacto",valor:"6 m\xB3"}],formula:"V \u2248 (0.5/3) \xB7 [1 + 4(1.125) + 2(2) + 4(4.375) + 9]",formulaTex:"V \\approx \\frac{0.5}{3}\\left[1+4(1.125)+2(2)+4(4.375)+9\\right]",interpretacion:"El \xE1rea de la secci\xF3n crece muy r\xE1pido con la altura. El trapecio se quedar\xEDa corto, pero Simpson ajusta par\xE1bolas y reproduce exactamente el polinomio c\xFAbico.",pasos:["h = (2 \u2212 0)/4 = 0.5. Nodos: 0; 0.5; 1; 1.5; 2.","A evaluada: 1; 1.125; 2; 4.375; 9.","Suma con coeficientes 1-4-2-4-1: 1 + 4.5 + 4 + 17.5 + 9 = 36.","V \u2248 (0.5/3)\xB736 = 6 m\xB3 exactos. Error: 0."],algoritmo:"Cuatro subintervalos y dos par\xE1bolas cubren todo el perfil.",criterio:"El exacto es 6 y Simpson da 6: error cero, porque el integrando es de grado 3. Con el trapecio, en cambio, el resultado ser\xEDa 6.25, un 4.17 % alto.",conclusion:"El volumen calculado es 6 m\xB3, exactamente el valor anal\xEDtico. Este ejemplo muestra la ventaja decisiva de Simpson: para perfiles polin\xF3micos de hasta grado 3 no hay error de truncamiento, por m\xE1s grande que sea el intervalo.",calculo:{funcion:"x^3 + 1",a:0,b:2,n:4,valorExacto:6,etiqueta:"Volumen de perfil c\xFAbico"}}],a=[{id:"si-ej-num-1",titulo:"Ejercicio 1 \xB7 Exponencial en [0, 1]",tipo:"numerico",planteamiento:"Aproximar \u222B\u2080\xB9 e\u02E3 dx con Simpson y n = 4, y comparar con e \u2212 1 = 1.7182818.",parametros:[{etiqueta:"f(x)",valor:"e\u02E3 (escribila como exp(x))"},{etiqueta:"Intervalo",valor:"[0, 1]"},{etiqueta:"n",valor:"4 (par)"},{etiqueta:"Valor exacto",valor:"e \u2212 1 = 1.7182818"}],pista:"Coeficientes 1-4-2-4-1. El error debe ser del orden de 10\u207B\u2075, no de 10\u207B\xB3.",interpretacion:"La exponencial es suave y muy bien comportada: es el caso donde Simpson luce su orden 4.",pasos:["h = 0.25. f evaluada: 1; 1.2840254; 1.6487213; 2.1170000; 2.7182818.","Suma: 1 + 5.1361017 + 3.2974425 + 8.4680001 + 2.7182818 = 20.6198261.","I \u2248 (0.25/3)\xB720.6198261 = 1.7183188.","Error absoluto: 0.0000371; error relativo: 0.0022 %."],algoritmo:"Dos par\xE1bolas (n = 4) con coeficientes 1-4-2-4-1.",criterio:"El error es 0.0000371, unas 240 veces menor que el del trapecio con el mismo n (0.0089401).",conclusion:"La integral es 1.7183188, frente a 1.7182818 exacta: 0.0022 % de error. Con tan pocos puntos, el resultado ya es de cuatro cifras significativas.",calculo:{funcion:"exp(x)",a:0,b:1,n:4,valorExacto:Math.E-1},cuestionario:[{id:"q1",tipo:"opcion-multiple",enunciado:"\xBFQu\xE9 ventaja tiene Simpson frente al trapecio con el mismo n?",opciones:[{id:"a",texto:"Usa menos evaluaciones de f."},{id:"b",texto:"El error baja como h\u2074 en vez de h\xB2."},{id:"c",texto:"No necesita que f sea continua."},{id:"d",texto:"Funciona con n impar."}],correcta:"b",explicacion:"Ambos usan los mismos n + 1 nodos. La diferencia es el orden: Simpson ajusta par\xE1bolas y su error es proporcional a h\u2074."},{id:"q2",tipo:"opcion-multiple",enunciado:"\xBFDe d\xF3nde sale el factor 0.25/3 en I \u2248 (0.25/3)\xB720.6198261?",opciones:[{id:"a",texto:"De h/3 con h = 0.25."},{id:"b",texto:"De h/2 con h = 0.25."},{id:"c",texto:"De dividir la suma entre n = 4."},{id:"d",texto:"De multiplicar 20.6198261 por 0.25."}],correcta:"a",explicacion:"Simpson compuesto multiplica la suma ponderada por h/3; con h = 0.25 da 0.25/3."},{id:"q3",tipo:"verdadero-falso",enunciado:"Con los coeficientes 1-4-2-4-1, el valor central 1.6487213 entra multiplicado por 2.",opciones:[{id:"v",texto:"Verdadero"},{id:"f",texto:"Falso"}],correcta:"v",explicacion:"El patr\xF3n 1-4-2-4-1 pone 2 en el nodo central; 1.2840254 y 2.1170000 entran con 4."}]},{id:"si-ej-num-2",titulo:"Ejercicio 2 \xB7 Logaritmo con seis subintervalos",tipo:"numerico",planteamiento:"Aproximar \u222B\u2081\xB2 (1/x) dx con Simpson y n = 6, y comparar con ln(2) = 0.6931472.",parametros:[{etiqueta:"f(x)",valor:"1/x"},{etiqueta:"Intervalo",valor:"[1, 2]"},{etiqueta:"n",valor:"6 (par)"},{etiqueta:"Valor exacto",valor:"0.6931472"}],pista:"Con n = 6 hay tres par\xE1bolas y los coeficientes son 1-4-2-4-2-4-1.",interpretacion:"La funci\xF3n decrece con curvatura. Simpson ya dio 0.015 % de error con n = 4; ahora deber\xEDa mejorar todav\xEDa m\xE1s.",pasos:["h = 1/6. Nodos: 1; 1.1666667; 1.3333333; 1.5; 1.6666667; 1.8333333; 2.","f evaluada: 1; 0.8571429; 0.75; 0.6666667; 0.6; 0.5454545; 0.5.","Suma 1-4-2-4-2-4-1: 1 + 3.4285714 + 1.5 + 2.6666667 + 1.2 + 2.1818182 + 0.5 = 12.4770563.","I \u2248 (1/18)\xB712.4770563 = 0.6931698. Error: 0.0000226 (0.0033 %)."],algoritmo:"Tres par\xE1bolas, coeficientes 1-4-2-4-2-4-1.",criterio:"Error 0.0000226, casi cinco veces menor que con n = 4 (0.0001068), consistente con el orden h\u2074 al pasar de 4 a 6.",conclusion:"El resultado es 0.6931698, con 0.0033 % de error. Para obtener algo parecido con el trapecio har\xEDa falta un n mucho mayor: esa es la diferencia pr\xE1ctica entre orden 2 y orden 4.",calculo:{funcion:"1/x",a:1,b:2,n:6,valorExacto:Math.LN2},cuestionario:[{id:"q1",tipo:"verdadero-falso",enunciado:"Simpson tambi\xE9n dar\xEDa ln(2) exacto si 1/x fuera un polinomio de grado 2.",opciones:[{id:"v",texto:"Verdadero"},{id:"f",texto:"Falso"}],correcta:"v",explicacion:"Simpson es exacta para todo polinomio de grado \u2264 3. Si el integrando fuera cuadr\xE1tico, el resultado ser\xEDa exacto con cualquier n par."},{id:"q2",tipo:"opcion-multiple",enunciado:"Los pasos eval\xFAan f en 1; 1.1666667; \u2026; 2. \xBFPor qu\xE9 se incluyen los extremos?",opciones:[{id:"a",texto:"Porque la suma ponderada usa los extremos y los nodos interiores."},{id:"b",texto:"Porque el valor exacto 0.6931472 es uno de los nodos."},{id:"c",texto:"Porque h = 1/6 solo se aplica a los extremos."},{id:"d",texto:"Porque Simpson promedia extremos en vez de integrar."}],correcta:"a",explicacion:"Los coeficientes 1-4-2-4-2-4-1 empiezan y terminan en 1: los extremos 1 y 2 tambi\xE9n entran en la suma."},{id:"q3",tipo:"opcion-multiple",enunciado:"El error pas\xF3 de 0.0001068 (n = 4) a 0.0000226 (n = 6). \xBFC\xF3mo se explica esa ca\xEDda?",opciones:[{id:"a",texto:"Por el orden h\u2074: al pasar de 4 a 6 el error baja m\xE1s de lo proporcional."},{id:"b",texto:"Porque 1/x se volvi\xF3 un polinomio."},{id:"c",texto:"Porque el valor exacto cambi\xF3."},{id:"d",texto:"Porque con n = 6 Simpson no tiene error."}],correcta:"a",explicacion:"El criterio lo dice: es consistente con el orden h\u2074 al pasar de 4 a 6."}]},{id:"si-ej-cas-1",titulo:"Ejercicio 3 \xB7 \xC1rea de un arco de seno con cuatro trozos",tipo:"numerico",planteamiento:"Aproximar \u222B de 0 a \u03C0 sin(x) dx con Simpson y n = 4, y comparar con 2.",parametros:[{etiqueta:"f(x)",valor:"sin(x)"},{etiqueta:"Intervalo",valor:"[0, \u03C0]"},{etiqueta:"n",valor:"4 (par)"},{etiqueta:"Valor exacto",valor:"2"}],pista:"h = \u03C0/4. Con solo dos par\xE1bolas, el resultado debe quedar a menos de 0.5 %.",interpretacion:"El seno es suave pero muy curvado. Comparar con el trapecio (que con n = 4 da 5.19 % de error) muestra el efecto de ajustar par\xE1bolas.",pasos:["h = \u03C0/4 \u2248 0.7853982. Nodos: 0; \u03C0/4; \u03C0/2; 3\u03C0/4; \u03C0.","f evaluada: 0; 0.7071068; 1; 0.7071068; 0.","Suma 1-4-2-4-1: 0 + 2.8284271 + 2 + 2.8284271 + 0 = 7.6568542.","I \u2248 (\u03C0/12)\xB77.6568542 = 2.0045598. Error: 0.0045598 (0.228 %)."],algoritmo:"Dos par\xE1bolas sobre [0, \u03C0/2] y [\u03C0/2, \u03C0].",criterio:"El error es 0.228 %, unas 23 veces menor que el del trapecio con el mismo n (5.19 %).",conclusion:"El \xE1rea aproximada es 2.0045598, frente a 2 exacta: 0.228 % de error. Con n = 4 el trapecio daba 1.8961; la par\xE1bola corrige casi todo el defecto de la recta.",calculo:{funcion:"sin(x)",a:0,b:Math.PI,n:4,valorExacto:2},cuestionario:[{id:"q1",tipo:"opcion-multiple",enunciado:"\xBFCu\xE1ntas par\xE1bolas distintos usa Simpson con n = 4?",opciones:[{id:"a",texto:"Una."},{id:"b",texto:"Dos: cada una cubre dos subintervalos."},{id:"c",texto:"Cuatro: una por subintervalo."},{id:"d",texto:"Ninguna: usa rectas."}],correcta:"b",explicacion:"Cada par\xE1bola pasa por tres nodos consecutivos, es decir, cubre dos subintervalos. Con n = 4 hay dos par\xE1bolas."},{id:"q2",tipo:"opcion-multiple",enunciado:"En la suma 0 + 2.8284271 + 2 + 2.8284271 + 0, \xBFde d\xF3nde sale 2.8284271?",opciones:[{id:"a",texto:"De 4\xB70.7071068, el nodo \u03C0/4 con coeficiente 4."},{id:"b",texto:"De 2\xB70.7071068, el nodo \u03C0/4 con coeficiente 2."},{id:"c",texto:"De sumar los extremos 0 y \u03C0."},{id:"d",texto:"De multiplicar h = \u03C0/4 por el valor exacto 2."}],correcta:"a",explicacion:"El patr\xF3n 1-4-2-4-1 da coeficiente 4 a los nodos \u03C0/4 y 3\u03C0/4, donde f vale 0.7071068."},{id:"q3",tipo:"verdadero-falso",enunciado:"Con n = 4 el error de Simpson es 0.228 %, unas 23 veces menor que el 5.19 % del trapecio.",opciones:[{id:"v",texto:"Verdadero"},{id:"f",texto:"Falso"}],correcta:"v",explicacion:"El criterio lo afirma: con los mismos nodos, la par\xE1bola corrige casi todo el defecto de la recta."}]},{id:"si-ej-cas-2",titulo:"Ejercicio 4 \xB7 Volumen de un tanque con perfil c\xFAbico",tipo:"casuistica",enunciado:"La secci\xF3n de un tanque es A(h) = 0.5h\xB3 + 2 m\xB2 a la altura h, de 0 a 2 m. El volumen es V = \u222B\u2080\xB2 (0.5h\xB3 + 2) dh. Estimarlo con Simpson y n = 6, sabiendo que el valor exacto es 6 m\xB3.",extraccion:{busqueda:"Se busca el volumen total integrando el \xE1rea de la secci\xF3n transversal.",datos:[{simbolo:"A(h)",valor:"0.5h\xB3 + 2 m\xB2",queEs:"\xC1rea de la secci\xF3n a cada altura."},{simbolo:"h",valor:"de 0 a 2 m",queEs:"Altura del tanque."},{simbolo:"V",valor:"\u222B\u2080\xB2 A(h) dh",queEs:"Volumen total, en m\xB3."}],formulacion:"El volumen es la integral del \xE1rea. El integrando es un polinomio c\xFAbico, as\xED que Simpson deber\xEDa dar el valor exacto."},planteamiento:"Aproximar V = \u222B\u2080\xB2 (0.5h\xB3 + 2) dh con Simpson y n = 6, y comparar con 6 m\xB3.",parametros:[{etiqueta:"A(h)",valor:"0.5h\xB3 + 2"},{etiqueta:"Intervalo",valor:"[0, 2] m"},{etiqueta:"n",valor:"6 (par)"},{etiqueta:"Valor exacto",valor:"6 m\xB3"}],pista:"Es un polinomio de grado 3: Simpson lo integra sin error, incluso con n = 4.",interpretacion:"El \xE1rea crece con el cubo de la altura. La par\xE1bola de Simpson reproduce exactamente ese crecimiento en cada bloque.",pasos:["h = 2/6 = 1/3 \u2248 0.3333333. Nodos: 0; 1/3; 2/3; 1; 4/3; 5/3; 2.","A evaluada: 2; 2.0185185; 2.1481481; 2.5; 3.1851852; 4.3148148; 6.","Suma 1-4-2-4-2-4-1: 2 + 8.0740741 + 4.2962963 + 10 + 6.3703704 + 17.2592593 + 6 = 54.","V \u2248 (1/9)\xB754 = 6 m\xB3 exactos. Error: 0."],algoritmo:"Tres par\xE1bolas sobre el perfil; coeficientes 1-4-2-4-2-4-1.",criterio:"El resultado es exactamente 6 porque el integrando es c\xFAbico. Es la comprobaci\xF3n pr\xE1ctica de que Simpson es exacta hasta grado 3.",conclusion:"El volumen es 6 m\xB3, sin error de truncamiento. Para perfiles polin\xF3micos de grado \u2264 3 no hace falta refinar n: el m\xE9todo acierta con cualquier n par. Para perfiles reales, en cambio, conviene duplicar n y verificar.",calculo:{funcion:"0.5*x^3 + 2",a:0,b:2,n:6,valorExacto:6,etiqueta:"Volumen de tanque c\xFAbico"},cuestionario:[{id:"q1",tipo:"opcion-multiple",enunciado:"\xBFPor qu\xE9 el resultado es exacto?",opciones:[{id:"a",texto:"Porque n = 6 es grande."},{id:"b",texto:"Porque el integrando es un polinomio de grado \u2264 3."},{id:"c",texto:"Porque el volumen siempre es exacto."},{id:"d",texto:"Porque h es peque\xF1o."}],correcta:"b",explicacion:"Simpson integra exactamente polinomios hasta grado 3, sin importar el tama\xF1o de h."},{id:"q2",tipo:"opcion-multiple",enunciado:"Seg\xFAn los datos del problema, \xBFqu\xE9 se integra para obtener el volumen del tanque?",opciones:[{id:"a",texto:"El \xE1rea de la secci\xF3n A(h) a lo largo de la altura, entre 0 y 2 m."},{id:"b",texto:"La altura h respecto del \xE1rea de la secci\xF3n."},{id:"c",texto:"El caudal de entrada en el tiempo."},{id:"d",texto:"La derivada del \xE1rea respecto de la altura."}],correcta:"a",explicacion:"Los datos muestran A(h) en m\xB2 integrada entre 0 y 2 m: el resultado es un volumen en m\xB3."},{id:"q3",tipo:"opcion-multiple",enunciado:"La pista dice que funciona incluso con n = 4, pero el ejercicio usa n = 6. \xBFPor qu\xE9 sirven ambos?",opciones:[{id:"a",texto:"Porque ambos son pares y el integrando es de grado 3."},{id:"b",texto:"Porque 4 y 6 son m\xFAltiplos de 3."},{id:"c",texto:"Porque el volumen exacto es 6 m\xB3."},{id:"d",texto:"Porque con n = 4 el error es 0, pero con n = 6 no."}],correcta:"a",explicacion:"La conclusi\xF3n dice que el m\xE9todo acierta con cualquier n par y que no hace falta refinar un polinomio de grado \u2264 3."}]}];export{e as a,o as b,a as c};
